def minMalwareSpread(graph, initial):
    n = len(graph)
    parent = [i for i in range(n)]

    # Union Find: find with path compression
    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    # Union Find: union by root
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru

    # Build connected components
    for i in range(n):
        for j in range(n):
            if graph[i][j]:
                union(i, j)

    # Count size of each component
    size = [0] * n
    for node in range(n):
        root = find(node)
        size[root] += 1

    # For each component, count # of initial nodes inside
    infected = [0] * n
    for node in initial:
        root = find(node)
        infected[root] += 1

    ans = None
    max_saved = -1

    for node in sorted(initial):
        root = find(node)
        # Only if node is the only initial in its component
        if infected[root] == 1:
            saved = size[root]
            if saved > max_saved or (saved == max_saved and node < ans):
                ans = node
                max_saved = saved

    # If no node can save any component, return min(initial)
    return ans if ans is not None else min(initial)
